                } else {
                        g_debug("unhandled tag %s from root", fu_coswid_tag_to_string(tag_id));
                }
        }

        /* device not supported */
        if (fu_firmware_get_id(firmware) == NULL && fu_firmware_get_version(firmware) == NULL &&
